<section class="dashboard-panel security-card settings-card settings-card--danger">
    <header><div><p class="dashboard-eyebrow">Danger zone</p><h2>Delete account</h2><p>Remove your account and its associated private data.</p></div><span class="security-status">Irreversible</span></header>
    <div class="security-card__body"><p class="settings-card__lead">Download anything you need before continuing. This action cannot be undone.</p><button type="button" class="dashboard-button settings-danger-button" wire:click="confirmUserDeletion" wire:loading.attr="disabled">Delete account</button></div>
    <x-dialog-modal wire:model.live="confirmingUserDeletion"><x-slot name="title">Delete account</x-slot><x-slot name="content">Enter your password to permanently delete your account.<div class="confirm-password-field" x-data="{}" x-on:confirming-delete-user.window="setTimeout(()=>$refs.password.focus(),250)"><x-input type="password" autocomplete="current-password" placeholder="Password" x-ref="password" wire:model="password" wire:keydown.enter="deleteUser"/><x-input-error for="password"/></div></x-slot><x-slot name="footer"><x-secondary-button wire:click="$toggle('confirmingUserDeletion')">Cancel</x-secondary-button><x-danger-button class="ms-3" wire:click="deleteUser" wire:loading.attr="disabled">Delete account</x-danger-button></x-slot></x-dialog-modal>
</section>
